-- 09I9_GAME_GUIDE | ModuleScript | ReplicatedStorage | V67 (SUBSTITUIR)
-- Conhecimento das funções reais do jogo. Não inventa botões, preços ou permissões.
local Rep=game:GetService('ReplicatedStorage');local Styles=require(Rep:WaitForChild('09I8_AVATAR_STYLES'))
local M={Version='V67',Topics={}}
local data={
 {'catalog','Catálogo','catalogo,shop,loja de roupas','Abra Catálogo no topo. Escolha categoria e subcategoria, pesquise uma peça e toque nela para ver as informações. Experimentar muda seu look de edição; confira a prévia e o personagem no mapa. Arraste o avatar para girá-lo. Aplicar confirma o look; Salvar abre o nome da combinação. Os itens vestidos ficam embaixo, com X para remover.'},
 {'filters','Filtros e preços','filtro,subcategoria,gratis,pagos,preco','No Catálogo, escolha a categoria e a subcategoria destacada. Abra Filtros para preço mínimo/máximo, roupas 2D ou camadas 3D e outras opções; depois toque Aplicar filtros. Os pagos aparecem primeiro; a busca de gratuitos é separada. Um valor vazio não é o mesmo que zero. O preço é consultado no Roblox e pode mudar.'},
 {'body','Corpo e roupas 3D','corpo,camadas,r15,r6,abacaxi,pernas','Configurar corpo ajusta as proporções permitidas; Aplicar envia o resultado ao mapa. Corpos de pacote e roupas em camadas usam R15. R6 mantém o formato clássico. Uma roupa 3D precisa carregar suas malhas/cages; se o Roblox não confirmar, o jogo preserva o último avatar válido e registra a etapa no Output. Não remova o corpo só porque uma roupa parece grande.'},
 {'zero','Avatar do zero','do zero,novo avatar,zerar avatar','Em Meus looks, toque Do zero. Escolha uma base R15/R6 ou mantenha o corpo atual sem roupas, escolha a cor e veja a prévia. Criar e editar confirma a troca e abre o Catálogo. O look anterior fica no histórico de edição; Desfazer permite voltar. Seus looks salvos não são apagados.'},
 {'apply','Aplicar e restaurar','aplicar,restaurar,desfazer,refazer','Experimentar prepara o look; o editor envia as mudanças ao personagem e Aplicar permite confirmar novamente. Restaurar pede confirmação e volta ao avatar original da sessão. Desfazer e Refazer percorrem o histórico de edição. Aplicar uma peça deve preservar as outras; aplicar um look completo substitui a combinação.'},
 {'saved','Meus looks','meus looks,salvar look,look salvo,salvar avatar','No Catálogo, toque Salvar, escreva um nome e escolha o rig compatível. Em Meus looks, pesquise pelo nome e selecione um card para ver a prévia e os itens. Usar look leva a combinação ao editor; Salvar alterações atualiza o registro selecionado. Mais reúne restaurar, publicar/retirar e excluir. Excluir pede confirmação. ↻ (Recarregar) consulta os dados novamente se a leitura estiver pendente.'},
 {'cart','Carrinho','carrinho,comprar item,comprar roupa','O Carrinho separa as peças do look dos itens selecionados para compra. Confira preço, disponibilidade e o que já possui; escolha quais comprar. Os prompts e a cobrança são do Roblox. Experimentar uma roupa não é comprá-la. Você pode remover itens da seleção pelo X; um prompt fechado não comprova pagamento.'},
 {'community','Looks da comunidade','comunidade,look de jogador,skins de jogadores','Abra Looks da comunidade. Todos inclui looks publicados e avatares registrados de jogadores; Grátis filtra os preços confirmados como gratuitos. A pesquisa aceita código e @jogador. Toque num look para girar a prévia, ver os itens e decidir se quer usar ou favoritar. Carregar mais consulta outro lote; o jogo recicla cards para manter a tela leve.'},
 {'codes','Códigos de looks','codigo,codigos,av-,ap-,lk-','O código identifica um look ou avatar registrado. Copie o código mostrado e pesquise na comunidade; não é ID de roupa nem senha. AV identifica avatar de jogador e outros prefixos são gerados pelo arquivo/publicação. Um código só funciona depois de o servidor confirmar o registro.'},
 {'publish','Publicar meu look','publicar look,retirar look','Em Meus looks, selecione a combinação e abra Mais → Publicar. Confirme o nome; o servidor salva a combinação e devolve um código para a comunidade. Se já estiver publicada, a opção muda para Retirar. Isso não coloca as roupas à venda no Marketplace e não transfere a autoria dos itens.'},
 {'sponsor','Patrocinar grátis','patrocinar,destaque,patrocinio','Abra Patrocinar + IA e escolha Itens, Jogos ou Comunidades. Use nome/ID e filtros para procurar. Em Publicar grátis, confira o registro e confirme o envio por 24 horas. Cada categoria tem limite por pessoa, sem prioridade paga. Em Itens entram itens pagos; exemplos temporários dão lugar a cada publicação real. Jogos e Comunidades começam apenas com os registros da praça.'},
 {'favorites','Favoritos e curtidas','favorito,favoritar,curtir,curtida','O coração salva ou curte o registro indicado. Nos destaques, favoritos e curtidas pertencem à vitrine do jogo, não alteram automaticamente os contadores públicos do site Roblox. Use o filtro de favoritos para reencontrar itens. Curtir não compra, aplica ou patrocina o registro.'},
 {'players','Ver outro jogador','outro jogador,tocar no jogador,ver roupa','Toque em um jogador no mapa para abrir o painel pequeno com prévia. Ver roupa mostra os itens; Curtir registra a reação; Usar look copia quando o dono permite; Enviar Robux abre a opção oficial quando disponível. A permissão de uso é conferida novamente pelo servidor.'},
 {'privacy','Privacidade do avatar','privacidade,permissao de copia,bloquear copia','Abra a engrenagem → Privacidade para permitir ou bloquear o uso do seu look dentro deste jogo. A prévia pode continuar visível, mas copiar/aplicar respeita sua escolha. Não compartilhe senha ou conta Roblox para compartilhar looks ou o acesso interno da IA.'},
 {'transfer','Enviar Robux e Plus','robux para jogador,enviar robux,doar robux,plus','Enviar Robux usa a janela e as verificações oficiais do Roblox; disponibilidade depende da elegibilidade da conta e do serviço. O botão Plus abre o plano oficial. O jogo não libera essa elegibilidade nem pede senha. Veja o valor e a divisão na confirmação nativa antes de aceitar. Não há vantagem nas partidas por transferir Robux.'},
 {'photo','Photo Mode','photo mode,modo foto,estudio,fotografar','Abra o botão de estúdio de avatar. Uma cópia do seu look fica no cenário de foto; seu personagem real continua no mapa. Fundos escolhe a imagem, Emotes anima a cópia, Pose edita articulações e Câmera ajusta o enquadramento. Feche qualquer painel pelo X para voltar à composição.'},
 {'background','Fundos da loja','fundo,fundos,background','No Photo Mode, Fundos abre a loja de AvatarBackground do Roblox. Testar lê a imagem do recipiente no servidor e verifica se ela carrega antes de trocar o fundo. Comprar depende do prompt oficial. Um ID de fundo não é o ID da imagem interna; permissões/moderação podem impedir o carregamento. Se isso acontecer, o fundo anterior é preservado.'},
 {'emote','Emotes na cópia','emote,emotes,danca,dancar','No Catálogo, abra Emotes e toque Testar emote para animar a prévia. Em Photo Mode → Emotes, pesquise na lista lateral e toque em Testar. O servidor resolve o item de emote para sua animação; o Animator toca essa animação na cópia R15. Ajuste velocidade/loop, pare ou congele a posição para editar a pose. Animações que o Roblox não permite carregar mostram falha; não é preciso comprar para tentar a prévia.'},
 {'pose','Editar pose','pose,braco,articulacao','Abra Pose no Photo Mode e selecione uma articulação no boneco/na cópia. Ajuste o movimento disponível e confirme para manter a posição. Ao editar, o emote é congelado para não disputar com a pose. Use desfazer/refazer/resetar para corrigir uma alteração. Mudar a pose da cópia não move outros jogadores.'},
 {'camera','Câmera e vídeo','camera,orbitar,video,movimento para video','No Photo Mode, Câmera ajusta enquadramento, zoom, ângulo e outros controles. Movimentos para vídeo oferece trajetos suaves como órbita; você pode pausar e voltar ao enquadramento inicial. Girar o avatar muda a cópia; mover a câmera muda o ponto de vista. No Catálogo, arrastar gira apenas o avatar.'},
 {'capture','Tirar e salvar foto','tirar foto,salvar foto,compartilhar foto,captura','Em Foto, tire a imagem e espere a confirmação. Salvar última foto e Compartilhar última foto usam as janelas nativas do Roblox. Cancelar não salva. Se o dispositivo não oferecer a função ou ocorrer timeout, tente novamente no aplicativo publicado; a roupa e os looks salvos continuam guardados.'},
 {'music','Música','musica,musicas,audio,som,volume','Abra o ícone de música para ver biblioteca, fila e salvos. Escolha uma sugestão ou cole ID/link de áudio e toque Carregar. Salvar guarda a faixa; + Fila adiciona à sequência. Ajuste volume ou mudo no player. Ao falhar o carregamento, o jogo tenta outra faixa disponível com limite de tentativas; Recarregar consulta novamente. O volume é pessoal e nem todo áudio tem permissão neste jogo.'},
 {'world','Mundos e mapa','mundo,mundos,mapa,mapas,nuvens','Engrenagem → Mudar mundo troca apenas o visual da praça para você. Cada tema usa iluminação e cores próprias; o centro fica livre para avatares. O chão visual é reutilizado ao caminhar, enquanto o piso e o reaparecimento são controlados pelo servidor. Trocar mundo não compra itens nem altera a praça dos outros.'},
 {'settings','Configurações','configuracao,configuracoes,ajustes,engrenagem','A engrenagem abre Mudar mundo, Som, Câmera, Aparência, Privacidade e Comandos. Escolha a categoria e use Voltar para retornar. Aparência permite tema/atalhos e reduzir animações. O X fecha as configurações. Algumas opções são pessoais e não mudam o jogo dos outros.'},
 {'commands','Comandos pessoais','comando,comandos,/fly,/unfly,voar','Engrenagem → Comandos mostra a lista que o servidor aceita e a função de cada comando. /fly ativa voo e /unfly para. Velocidade, salto e tamanho têm limites do jogo e afetam apenas você. Durante partidas competitivas, mudanças de movimento ficam desativadas para manter as mesmas condições.'},
 {'games','Salão de jogos','jogos,jogar,sala,salas,bots','Abra Jogos e escolha Truco, Dama ou Xadrez no topo. Partida rápida procura oponente; Criar sala gera um código; Tenho um código entra em uma sala; Jogar com companhia abre os perfis de bots. Nico é iniciante, Lia equilibrada e Dante estrategista. As partidas são 2D. Ao terminar, confira o placar da sessão e a opção de revanche.'},
 {'chess','Xadrez','xadrez,chess,xeque','No Xadrez, toque em uma peça sua e escolha uma casa legal. Você não pode deixar seu rei em xeque. O jogo verifica as jogadas, incluindo regras especiais quando aplicáveis. O objetivo é dar xeque-mate. Na tela da partida ficam turno, estado, saída e ações disponíveis; o tabuleiro é 2D e não teleporta seu personagem.'},
 {'checkers','Dama','dama,damas,checkers','Na Dama, selecione uma peça e uma casa indicada. As capturas e sequências são verificadas pelo servidor conforme as regras implementadas; ao chegar ao outro lado, a peça vira dama. Observe de quem é o turno e se há captura obrigatória. O tabuleiro é 2D, com partida, resultado e revanche.'},
 {'truco','Truco e duplas','truco,vaza,manilha,baralho cheio','No Truco, escolha Paulista, Mineiro ou Goiano e confira o baralho antes de começar. Cada jogador recebe três cartas; você pode escolher qualquer carta da sua mão. As duplas e donos das cartas são identificados na mesa. TRUCO aumenta o valor da mão; o outro lado tem dez segundos para aceitar, aumentar ou correr. As manilhas e desempates seguem a variante escolhida.'},
 {'cards','Visuais de cartas','baralho,cartas,visual da carta,skins de cartas','Em Jogos → Baralhos, veja os visuais e compre diretamente pelos valores mostrados. O visual altera a aparência, preservando valor e naipe; não melhora a carta. Equipe no inventário. Em Privacidade → Visuais das cartas você escolhe ver seu baralho, o de cada jogador ou o clássico. Caixas aleatórias não fazem parte da loja atual.'},
 {'atelier','Ateliê de cartas','atelie,editar foto,imagem da carta','No Ateliê, use um ID/link de imagem carregada no Roblox. Carregar e Recarregar verificam a imagem antes da prévia; ajuste os controles disponíveis, guarde uma versão e equipe. Permissão/moderação pode impedir o uso mesmo com ID existente. O editor muda apenas o visual das cartas e depende do acesso previsto na loja.'},
 {'coins','Moedas','moeda,moedas,ganhar partida','O saldo de moedas aparece no salão de jogos. Partidas elegíveis e concluídas podem conceder recompensas conforme as regras do servidor; desistir ou repetir movimentos não garante moedas. Confira preços de visuais na loja. Comprar aparência não muda força de cartas, peças, bots ou regras.'},
 {'tournament','Torneios','torneio,torneios,convite','Abra Torneios no salão para ver classificação e convites disponíveis. Responda dentro do prazo mostrado e observe o horário da competição. A participação não exige apostar Robux. Convites, disponibilidade e substituições são controlados pelo servidor; o painel mostra o estado atual.'},
 {'ai','Estilos e IA de looks','ia,estilo,estilos,assistente','Descreva uma ideia ou abra Explorar estilos. Escolha estilo, orçamento, roupa 2D/3D e se quer manter suas peças. Confirme para buscar itens reais. Camisa e calça têm prioridade em looks completos; os opcionais dependem do orçamento. Veja a prévia e os itens antes de usar. É um planejador do catálogo com guia do jogo, sem chave externa e sem prometer respostas gerais sobre qualquer assunto.'},
 {'history','Conversas e histórico','conversa,conversas,historico,chats,arquivar,renomear','A barra lateral tem Nova conversa, pesquisa e histórico. Toque num chat para abrir o texto; o menu … permite renomear, arquivar ou excluir com confirmação. Conversas arquivadas abre o arquivo. São até 20 conversas com as últimas 16 mensagens salvas por conversa. A gravação é agrupada e depende do DataStore; uma falha é informada. Abrir o histórico não recupera automaticamente os modelos 3D de uma geração antiga.'},
 {'chatshare','Compartilhar conversa','compartilhar conversa,codigo ch-,partilhar conversa','Compartilhar fica no topo da IA. Criar código público confirma uma cópia das últimas oito mensagens, filtrada pelo Roblox e válida por sete dias. Selecione o código para copiar. Abrir um código CH- permite ler uma cópia compartilhada. Isso não dá acesso à conta Roblox nem aos outros chats; novas mensagens ficam na sua cópia privada.'},
 {'season','Halloween opcional','halloween,halowem,tema,neutro','Configurações → Aparência → Tema permite Automático, Neutro ou Halloween ligado. No automático, os enfeites terminam em 1º de novembro às 00h de Brasília. Você pode desligar antes ou manter ligado manualmente. Os enfeites são limitados e não cobrem controles, cartas ou a prévia do avatar.'},
 {'account','Conta interna e planos','plano,conta da ia,compartilhar conta','A conta interna da IA usa seu jogador Roblox e pode compartilhar o acesso interno pelos controles disponíveis; nunca compartilhe senha Roblox. Compras antigas de planos mantêm seus prazos e permissões conforme os recibos. Novas compras de planos estão encerradas. Nova conversa limpa a conversa atual, preservando os looks e coleções salvas; pedidos de ajuda não consomem busca de looks.'},
}
for _,r in ipairs(data)do local t={id=r[1],name=r[2],answer=r[4],note='Como usar '..r[2]:lower(),aliases={}};for a in r[3]:gmatch('[^,]+')do t.aliases[#t.aliases+1]=Styles.Normalize(a)end;M.Topics[#M.Topics+1]=t end
function M.Find(raw)
 local s=' '..Styles.Normalize(raw):gsub('[^%w/]',' '):gsub('%s+',' ')..' ';local best,score
 local broad={jogar=true,jogos=true,sala=true,salas=true,gratis=true,pagos=true,preco=true,ia=true,estilo=true,estilos=true}
 for _,topic in ipairs(M.Topics)do for _,alias in ipairs(topic.aliases)do
  local a=alias:gsub('[^%w/]',' '):gsub('%s+',' ');local rank=#alias-(broad[alias]and 5 or 0)
  if(s:find(' '..a..' ',1,true)or s:find(' '..a..'s ',1,true))and(not score or rank>score)then best,score=topic,rank end
 end end;return best
end
function M.IsQuestion(raw)
 local s=Styles.Normalize(raw)
 return tostring(raw):find('?',1,true)~=nil or s:match('^qual%s')~=nil or s:match('^quais%s')~=nil or s:match('^pra que%s')~=nil or s:match('^para que%s')~=nil or s:match('^como%s')~=nil or s:match('^onde%s')~=nil or s:match('^o que%s')~=nil or s:match('^porque%s')~=nil or s:match('^por que%s')~=nil or s:match('^how%s')~=nil or s:match('^where%s')~=nil or s:find('me explica',1,true)~=nil or s:find('me ensina',1,true)~=nil or s:find('nao funciona',1,true)~=nil or s:find('nao carrega',1,true)~=nil
end
function M.IsLookRequest(raw)
 local s=Styles.Normalize(raw);if M.IsQuestion(raw)or s:find('tirar ',1,true)or s:find('remover ',1,true)then return false end
 if Styles.Find(s)then return true end
 for _,w in ipairs({'look','skin','outfit','estilo','roupa','cabelo','acessorio','mais barato','troca','mude','preto','branco','azul','rosa','verde','roxo','mais','outra','outro'})do if s:find(w,1,true)then return true end end
 return false
end
function M.Answer(raw)
 local t=M.Find(raw);if t then return t.name..'\n\n'..t.answer end
 return'Posso explicar as funções deste jogo: Catálogo, corpo, Meus looks, carrinho, comunidade, patrocínio, Photo Mode, música, mundos, comandos e jogos. Abra Mais ajuda para escolher um assunto ou pergunte, por exemplo, “Como usar o catálogo?”. Para criar roupa, escolha um estilo e confirme as opções.'
end
return M
